<?php
namespace App\Modules\CashManagement\Presentation\Http\Controllers;
use App\Http\Controllers\Controller;use App\Modules\CashManagement\Application\ExpectedCashSessionBalance;use App\Modules\CashManagement\Application\FinancialAccountBalance;use App\Modules\CashManagement\Domain\Enums\CashSessionStatus;use App\Modules\CashManagement\Domain\Models\CashSession;use App\Modules\CashManagement\Domain\Models\CashTransfer;use App\Modules\Finance\Domain\Enums\FinancialAccountType;use App\Modules\Finance\Domain\Models\FinancialAccount;use App\Modules\Identity\Domain\Models\AuthorizationRequest;use Illuminate\Http\Request;use Inertia\Inertia;use Inertia\Response;
class ListCashController extends Controller {public function __invoke(Request $request,FinancialAccountBalance $balances,ExpectedCashSessionBalance $expected):Response{abort_unless($request->user()->hasPermission('cash.operate')||$request->user()->hasPermission('cash.open'),403);$accounts=FinancialAccount::query()->where('account_type',FinancialAccountType::Asset)->where('is_active',true)->orderBy('name')->get()->map(fn($a)=>[...$a->only(['id','code','name','accepts_payments']),'balance'=>$balances->execute($a->id)]);$session=CashSession::query()->with(['account:id,name','opener:id,name'])->where('status',CashSessionStatus::Open)->latest('opened_at')->first();$authorizations=$session?AuthorizationRequest::query()->where('resource_type',$session->getMorphClass())->where('resource_id',$session->id)->where('approval_permission','cash.authorize-difference')->get()->filter->isUsable()->map(fn($a)=>['id'=>$a->id,'reason'=>$a->reason])->values():[];return Inertia::render('cash/Index',['accounts'=>$accounts,'totalCash'=>$accounts->sum('balance'),'session'=>$session?[...$session->only(['id','opening_amount']),'account'=>$session->account->name,'opened_at'=>$session->opened_at->format('Y-m-d H:i'),'opener'=>$session->opener->name,'expected'=>$expected->execute($session)]:null,'recentSessions'=>CashSession::query()->with('account:id,name')->where('status',CashSessionStatus::Closed)->latest('closed_at')->limit(10)->get()->map(fn($s)=>[...$s->only(['id','expected_closing_amount','counted_closing_amount','difference_amount']),'account'=>$s->account->name,'closed_at'=>$s->closed_at->format('Y-m-d H:i')]),'transfers'=>CashTransfer::query()->with(['fromAccount:id,name','toAccount:id,name'])->latest('transferred_at')->limit(10)->get()->map(fn($t)=>['id'=>$t->id,'document_number'=>$t->document_number,'from'=>$t->fromAccount->name,'to'=>$t->toAccount->name,'amount'=>$t->amount,'at'=>$t->transferred_at->format('Y-m-d H:i')]),'authorizations'=>$authorizations,'threshold'=>(int)config('business.cash_difference_authorization_threshold',10000),'now'=>now()->format('Y-m-d\TH:i'),'canOpen'=>$request->user()->hasPermission('cash.open'),'canClose'=>$request->user()->hasPermission('cash.close'),'canOperate'=>$request->user()->hasPermission('cash.operate'),'canRequestAuthorization'=>$request->user()->hasPermission('authorizations.request')]);}}
